  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g, function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }
  function paras(t){ return String(t||"").split(/\n\n+/).map(function(p){ return "<p>" + esc(p.replace(/\s+/g," ").trim()) + "</p>"; }).join(""); }
